import { platform, version, arch, locale } from '@tauri-apps/api/os';
import { getVersion } from '@tauri-apps/api/app';

interface Diagnostics {
  app_version: string;
  platform: string;
  os_version: string;
  locale: string;
  tauri: boolean;
  recent_log_tail?: string;
}

export async function collectDiagnostics(): Promise<Diagnostics> {
  const isTauri = '__TAURI__' in window;

  if (!isTauri) {
    return {
      app_version: import.meta.env.VITE_APP_VERSION || 'unknown',
      platform: 'browser',
      os_version: navigator.userAgent,
      locale: navigator.language,
      tauri: false
    };
  }

  try {
    const [appVersion, platformName, osVersion, archName, localeName] = await Promise.all([
      getVersion(),
      platform(),
      version(),
      arch(),
      locale()
    ]);

    const platformString = `${platformName}-${archName}`;

    // Collect recent log tail if available (last 50 lines or 2KB)
    let logTail: string | undefined;
    try {
      // Implement log collection based on app's logging strategy
      // This is a placeholder - adjust based on actual logging implementation
      logTail = undefined;
    } catch (e) {
      // Silently skip if logs unavailable
    }

    return {
      app_version: appVersion,
      platform: platformString,
      os_version: osVersion,
      locale: localeName || navigator.language,
      tauri: true,
      recent_log_tail: logTail
    };
  } catch (error) {
    console.error('Failed to collect diagnostics:', error);
    return {
      app_version: 'unknown',
      platform: 'unknown',
      os_version: 'unknown',
      locale: navigator.language,
      tauri: true
    };
  }
}
