import { collectDiagnostics } from './diagnostics';

interface FeedbackPayload {
  category: 'bug' | 'feature' | 'question';
  title: string;
  body: string;
  contact_email?: string;
  diagnostics_opt_in: boolean;
  diagnostics?: any;
  turnstile_token: string;
}

interface FeedbackDraft {
  category: string;
  title: string;
  body: string;
  contact_email: string;
  diagnostics_opt_in: boolean;
}

const DRAFT_KEY = 'animo_feedback_draft';
const FEEDBACK_ENDPOINT = import.meta.env.VITE_FEEDBACK_ENDPOINT || 'https://getanimo.app/api/feedback';

export function saveDraft(draft: FeedbackDraft): void {
  try {
    localStorage.setItem(DRAFT_KEY, JSON.stringify(draft));
  } catch (e) {
    console.warn('Failed to save feedback draft:', e);
  }
}

export function loadDraft(): FeedbackDraft | null {
  try {
    const draft = localStorage.getItem(DRAFT_KEY);
    return draft ? JSON.parse(draft) : null;
  } catch (e) {
    return null;
  }
}

export function clearDraft(): void {
  localStorage.removeItem(DRAFT_KEY);
}

export async function submitFeedback(
  draft: FeedbackDraft,
  turnstileToken: string
): Promise<{ ok: boolean; issue_url?: string; error?: string }> {
  const payload: FeedbackPayload = {
    category: draft.category as any,
    title: draft.title.slice(0, 120),
    body: draft.body.slice(0, 8000),
    contact_email: draft.contact_email || undefined,
    diagnostics_opt_in: draft.diagnostics_opt_in,
    turnstile_token: turnstileToken
  };

  if (draft.diagnostics_opt_in) {
    payload.diagnostics = await collectDiagnostics();
  }

  // Verify payload size
  const payloadSize = new Blob([JSON.stringify(payload)]).size;
  if (payloadSize > 16 * 1024) {
    return { ok: false, error: 'Feedback payload too large' };
  }

  try {
    const response = await fetch(FEEDBACK_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });

    const result = await response.json();

    if (response.ok) {
      clearDraft();
      return result;
    } else {
      return { ok: false, error: result.error || 'Submission failed' };
    }
  } catch (error) {
    return { ok: false, error: 'Network error' };
  }
}
