```typescript
import { Handler } from '@netlify/functions';
import { Octokit } from '@octokit/rest';

const GITHUB_TOKEN = process.env.GITHUB_TOKEN;
const TURNSTILE_SECRET = process.env.TURNSTILE_SECRET_KEY;
const GITHUB_REPO_OWNER = 'captaaint';
const GITHUB_REPO_NAME = 'animo';

const rateLimitMap = new Map<string, number[]>();
const RATE_LIMIT = 5;
const RATE_LIMIT_WINDOW = 60 * 60 * 1000; // 1 hour

function checkRateLimit(ip: string): boolean {
  const now = Date.now();
  const timestamps = rateLimitMap.get(ip) || [];
  const recentTimestamps = timestamps.filter(t => now - t < RATE_LIMIT_WINDOW);

  if (recentTimestamps.length >= RATE_LIMIT) {
    return false;
  }

  recentTimestamps.push(now);
  rateLimitMap.set(ip, recentTimestamps);
  return true;
}

async function verifyTurnstile(token: string, ip: string): Promise<boolean> {
  const response = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      secret: TURNSTILE_SECRET,
      response: token,
      remoteip: ip
    })
  });

  const result = await response.json();
  return result.success === true;
}

export const handler: Handler = async (event) => {
  // CORS headers
  const allowedOrigins = ['https://getanimo.app', 'tauri://localhost'];
  const origin = event.headers.origin || '';
  const corsHeaders = {
    'Access-Control-Allow-Origin': allowedOrigins.includes(origin) ? origin : '',
    'Access-Control-Allow-Headers': 'Content-Type',
    'Access-Control-Allow-Methods': 'POST'
  };

  if (event.httpMethod === 'OPTIONS') {
    return { statusCode: 204, headers: corsHeaders, body: '' };
  }

  if (event.httpMethod !== 'POST') {
    return { statusCode: 405, headers: corsHeaders, body: JSON.stringify({ error: 'Method not allowed' }) };
  }

  // Check body size
  const bodySize = Buffer.byteLength(event.body || '', 'utf8');
  if (bodySize > 16 * 1024) {
    return { statusCode: 413, headers: corsHeaders, body: JSON.stringify({ error: 'Payload too large' }) };
  }

  let payload;
  try {
    payload = JSON.parse(event.body || '{}');
  } catch (e) {
    return { statusCode: 400, headers: corsHeaders, body: JSON.stringify({ error: 'Invalid JSON' }) };
  }

  // Validate payload
  const { category, title, body, contact_email, diagnostics_opt_in, diagnostics, turnstile_token } = payload;

  if (!['bug', 'feature', 'question'].includes(category)) {
    return { statusCode: 400, headers: corsHeaders, body: JSON.stringify({ error: 'Invalid category' }) };
  }

  if (!title || title.length > 120 || !body || body.length > 8000) {
    return { statusCode: 400, headers: corsHeaders, body: JSON.stringify({ error: 'Invalid title or body' }) };
  }

  // Rate limiting
  const ip = event.headers['x-forwarded-for']?.split(',')[0] || 'unknown';
  if (!checkRateLimit(ip)) {
    return { statusCode: 429, headers: corsHeaders, body: JSON.stringify({ error: 'Rate limit exceeded' }) };
  }

  // Verify Turnstile
  const turnstileValid = await verifyTurnstile(turnstile_token, ip);
  if (!turnstileValid) {
    return { statusCode: 403, headers: corsHeaders, body: JSON.stringify({ error: 'Invalid Turnstile token' }) };
  }

  // Create GitHub issue
  const octokit = new Octokit({ auth: GITHUB_TOKEN });

  let issueBody = body;
  if (diagnostics_opt_in && diagnostics) {
    issueBody += '\n\n---\n\n**Diagnostics:**\n\n```json\n' + JSON.stringify(diagnostics, null, 2) + '\n```';
  }
  if (contact_email) {
    issueBody += `\n\n**Contact:** ${contact_email}`;
  }

  try {
    const issue = await octokit.issues.create({
      owner: GITHUB_REPO_OWNER,
      repo: GITHUB_REPO_NAME,
      title: `[${category}] ${title}`,
      body: issueBody,
      labels: ['feedback', 'from-app']
    });

    return {
      statusCode: 200,
      headers: corsHeaders,
      body: JSON.stringify({ ok: true, issue_url: issue.data.html_url })
    };
  } catch (error) {
    console.error('GitHub API error:', error);
    return { statusCode: 500, headers: corsHeaders, body: JSON.stringify({ error: 'Failed to create issue' }) };
  }
};
```

