```typescript
import { UPDATE_MANIFEST_URL } from '../config';

interface UpdateInfo {
  available: boolean;
  currentVersion: string;
  latestVersion?: string;
  downloadUrl?: string;
  releaseNotes?: string;
  error?: string;
}

interface UpdateProgress {
  downloaded: number;
  total: number;
  percentage: number;
}

let updateModule: any = null;

async function loadUpdaterModule() {
  if (updateModule) return updateModule;

  const isTauri = '__TAURI__' in window;
  if (!isTauri) {
    return null;
  }

  try {
    updateModule = await import('@tauri-apps/plugin-updater');
    return updateModule;
  } catch (e) {
    console.warn('Updater plugin not available:', e);
    return null;
  }
}

async function sleep(ms: number) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

export async function checkForUpdates(): Promise<UpdateInfo> {
  const updater = await loadUpdaterModule();

  if (!updater) {
    return {
      available: false,
      currentVersion: import.meta.env.VITE_APP_VERSION || 'unknown',
      error: 'Updater not available'
    };
  }

  let lastError: Error | null = null;
  const maxRetries = 3;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      const update = await updater.check();

      if (!update) {
        return {
          available: false,
          currentVersion: await updater.currentVersion()
        };
      }

      return {
        available: true,
        currentVersion: await updater.currentVersion(),
        latestVersion: update.version,
        releaseNotes: update.body,
        downloadUrl: update.downloadUrl
      };
    } catch (error) {
      lastError = error as Error;
      if (attempt < maxRetries - 1) {
        const backoffMs = Math.pow(2, attempt) * 1000;
        await sleep(backoffMs);
      }
    }
  }

  return {
    available: false,
    currentVersion: import.meta.env.VITE_APP_VERSION || 'unknown',
    error: lastError?.message || 'Update check failed'
  };
}

export async function downloadAndInstall(
  onProgress?: (progress: UpdateProgress) => void
): Promise<{ success: boolean; error?: string }> {
  const updater = await loadUpdaterModule();

  if (!updater) {
    return { success: false, error: 'Updater not available' };
  }

  try {
    const update = await updater.check();

    if (!update) {
      return { success: false, error: 'No update available' };
    }

    await update.downloadAndInstall((event: any) => {
      if (event.event === 'Started') {
        onProgress?.({ downloaded: 0, total: event.data.contentLength || 0, percentage: 0 });
      } else if (event.event === 'Progress') {
        const percentage = (event.data.chunkLength / event.data.contentLength) * 100;
        onProgress?.({
          downloaded: event.data.chunkLength,
          total: event.data.contentLength,
          percentage
        });
      }
    });

    return { success: true };
  } catch (error) {
    return { success: false, error: (error as Error).message };
  }
}

export async function restartApp(): Promise<void> {
  const { relaunch } = await import('@tauri-apps/plugin-process');
  await relaunch();
}
