import { useState, useEffect } from 'react';
import { checkForUpdates, downloadAndInstall, restartApp } from '../helpers/updater';

interface UpdateBannerProps {
  updateInfo: any;
  onDismiss: () => void;
}

export function UpdateBanner({ updateInfo, onDismiss }: UpdateBannerProps) {
  const [downloading, setDownloading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [readyToInstall, setReadyToInstall] = useState(false);
  const [error, setError] = useState('');

  const handleDownload = async () => {
    setDownloading(true);
    setError('');

    const result = await downloadAndInstall((prog) => {
      setProgress(prog.percentage);
    });

    setDownloading(false);

    if (result.success) {
      setReadyToInstall(true);
    } else {
      setError(result.error || 'Download failed');
    }
  };

  const handleRestart = async () => {
    await restartApp();
  };

  if (!updateInfo.available) return null;

  return (
    <div className="update-banner">
      {!downloading && !readyToInstall && (
        <>
          <span>Update available: v{updateInfo.latestVersion}</span>
          <button onClick={handleDownload}>Download</button>
          <button onClick={onDismiss}>Dismiss</button>
        </>
      )}

      {downloading && (
        <>
          <span>Downloading update... {progress.toFixed(0)}%</span>
          <progress value={progress} max={100} />
        </>
      )}

      {readyToInstall && (
        <>
          <span>Update ready to install</span>
          <button onClick={handleRestart}>Restart now</button>
          <button onClick={onDismiss}>Later</button>
        </>
      )}

      {error && (
        <>
          <span>Error: {error}</span>
          <button onClick={handleDownload}>Retry</button>
          <button onClick={onDismiss}>Dismiss</button>
        </>
      )}
    </div>
  );
}
