import { UpdateBanner } from './components/UpdateBanner';
import { checkForUpdates } from './helpers/updater';

function Main() {
  const [updateInfo, setUpdateInfo] = useState(null);
  const [bannerDismissed, setBannerDismissed] = useState(false);

  useEffect(() => {
    // Check for updates 3 seconds after startup
    const autoCheckEnabled = localStorage.getItem('animo_auto_check_updates') !== 'false';
    if (autoCheckEnabled) {
      setTimeout(async () => {
        const info = await checkForUpdates();
        if (info.available) {
          setUpdateInfo(info);
        }
      }, 3000);
    }

    // Background check every 24 hours
    const interval = setInterval(async () => {
      if (autoCheckEnabled) {
        const info = await checkForUpdates();
        if (info.available) {
          setUpdateInfo(info);
          setBannerDismissed(false);
        }
      }
    }, 24 * 60 * 60 * 1000);

    return () => clearInterval(interval);
  }, []);

  return (
    <>
      {updateInfo && !bannerDismissed && (
        <UpdateBanner
          updateInfo={updateInfo}
          onDismiss={() => setBannerDismissed(true)}
        />
      )}
      {/* Rest of app */}
    </>
  );
}
